using System.ComponentModel;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration -----------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Tools -------------------------------------------------------------------

var notebook = new Notebook();

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        ([Description("The search query to look up on the web")] string query) =>
        {
            Console.WriteLine($"  🔍 Searching: \"{query}\"");
            return WebSearchSimulator.Search(query);
        },
        "web_search",
        "Searches the web for information on a topic. Returns a list of relevant snippets."),

    AIFunctionFactory.Create(
        (
            [Description("Short title for the note")] string title,
            [Description("The content to save")] string content
        ) =>
        {
            notebook.Add(title, content);
            Console.WriteLine($"  📝 Note saved: \"{title}\"");
            return $"Note '{title}' saved successfully.";
        },
        "save_note",
        "Saves a research note for later reference. Use this to record important findings."),

    AIFunctionFactory.Create(
        () =>
        {
            var notes = notebook.GetAll();
            Console.WriteLine($"  📖 Reading {notes.Count} note(s)");
            return notes.Count == 0
                ? "No notes have been saved yet."
                : JsonSerializer.Serialize(notes);
        },
        "read_notes",
        "Reads all previously saved research notes."),
};

// --- Agent -------------------------------------------------------------------

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When given a topic, you must:
        1. Search the web for information using the web_search tool (perform 2-3 searches with varied queries).
        2. Save important findings as notes using the save_note tool.
        3. Read your notes using read_notes, then produce a well-structured summary with key findings and sources.
        Be thorough but concise. Always cite your sources.
        """,
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and taking notes.",
    tools: tools);

// --- Run ---------------------------------------------------------------------

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the benefits and risks of large language models in healthcare";

Console.WriteLine($"🔬 Research Agent — investigating: \"{topic}\"\n");

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}");

Console.WriteLine("\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
Console.WriteLine("📋 RESEARCH SUMMARY");
Console.WriteLine("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n");
Console.WriteLine(response.Text);

// --- Supporting types --------------------------------------------------------

/// <summary>Simulates web search results for demonstration purposes.</summary>
static class WebSearchSimulator
{
    public static List<SearchResult> Search(string query)
    {
        var q = query.ToLowerInvariant();

        List<SearchResult> results =
        [
            new("Wikipedia", $"https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}",
                $"Overview article covering key aspects of {query}, including history, current state, and future directions."),

            new("Nature Reviews", "https://www.nature.com/articles/example",
                $"Peer-reviewed analysis examining the impact of {query} on modern research and industry practices."),

            new("MIT Technology Review", "https://www.technologyreview.com/example",
                $"In-depth feature exploring how {query} is transforming technology and society, with expert commentary."),
        ];

        if (q.Contains("risk") || q.Contains("safety") || q.Contains("concern"))
        {
            results.Add(new("WHO / Safety Board", "https://www.who.int/example",
                $"Report detailing potential risks and safety considerations related to {query}, with recommended guidelines."));
        }

        if (q.Contains("benefit") || q.Contains("advantage") || q.Contains("opportunity"))
        {
            results.Add(new("Harvard Business Review", "https://hbr.org/example",
                $"Case studies highlighting measurable benefits and ROI of {query} across multiple sectors."));
        }

        if (q.Contains("healthcare") || q.Contains("medical") || q.Contains("health"))
        {
            results.Add(new("The Lancet Digital Health", "https://www.thelancet.com/example",
                $"Clinical study on the application of {query} in patient care, diagnostics, and treatment planning."));
        }

        if (q.Contains("ai") || q.Contains("language model") || q.Contains("llm"))
        {
            results.Add(new("OpenAI Research", "https://openai.com/research/example",
                $"Technical paper on recent advances in {query}, discussing capabilities, limitations, and alignment research."));
        }

        return results;
    }
}

record SearchResult(string Source, string Url, string Snippet);

/// <summary>Simple in-memory notebook for the agent's research notes.</summary>
class Notebook
{
    private readonly List<Note> _notes = [];

    public void Add(string title, string content) =>
        _notes.Add(new Note(title, content, DateTime.UtcNow));

    public List<Note> GetAll() => [.. _notes];
}

